CREATE TABLE public.credit_wallets ( user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, balance integer NOT NULL DEFAULT 0 CHECK (balance >= 0), lifetime_earned integer NOT NULL DEFAULT 0 CHECK (lifetime_earned >= 0), lifetime_spent integer NOT NULL DEFAULT 0 CHECK (lifetime_spent >= 0), vip_tier text NOT NULL DEFAULT 'none' CHECK (vip_tier IN ('none', 'essencial', 'mensal', 'premium')), vip_until timestamp with time zone, last_ad_reward_at timestamp with time zone, created_at timestamp with time zone NOT NULL DEFAULT now(), updated_at timestamp with time zone NOT NULL DEFAULT now() );